import { useState } from "react";
import api from "../api";

export default function AddLevelWithTestCases() {
  const [form, setForm] = useState({
    level_no: "",
    title: "",
    description: "",
    testCases: [
      { input_data: "", expected_output: "" }
    ]
  });

  const handleChange = (e) => {
    setForm({ ...form, [e.target.name]: e.target.value });
  };

  const handleTestCaseChange = (index, e) => {
    const updated = [...form.testCases];
    updated[index][e.target.name] = e.target.value;
    setForm({ ...form, testCases: updated });
  };

  const addTestCase = () => {
    setForm({
      ...form,
      testCases: [...form.testCases, { input_data: "", expected_output: "" }]
    });
  };

  const removeTestCase = (index) => {
    const updated = form.testCases.filter((_, i) => i !== index);
    setForm({ ...form, testCases: updated });
  };

  const handleSubmit = async (e) => {
    e.preventDefault();

    try {
      await api.post("/levels", form);
      alert("✅ Problem + Test Cases added");

      setForm({
        level_no: "",
        title: "",
        description: "",
        testCases: [{ input_data: "", expected_output: "" }]
      });
    } catch (err) {
      console.error(err);
      alert("❌ Failed to add problem");
    }
  };

  return (
    <form onSubmit={handleSubmit} style={styles.form}>
      <h3 style={styles.heading}>➕ Add Problem</h3>

      <input
        style={styles.input}
        name="level_no"
        placeholder="Level Number"
        value={form.level_no}
        onChange={handleChange}
        required
      />

      <input
        style={styles.input}
        name="title"
        placeholder="Title"
        value={form.title}
        onChange={handleChange}
        required
      />

      <textarea
        style={styles.textarea}
        name="description"
        placeholder="Problem Description"
        value={form.description}
        onChange={handleChange}
        required
      />

      <h4 style={{ color: "#38bdf8" }}>Test Cases</h4>

      {form.testCases.map((tc, index) => (
        <div key={index} style={styles.testCase}>
          <input
            style={styles.input}
            name="input_data"
            placeholder="Input"
            value={tc.input_data}
            onChange={(e) => handleTestCaseChange(index, e)}
            required
          />

          <input
            style={styles.input}
            name="expected_output"
            placeholder="Expected Output"
            value={tc.expected_output}
            onChange={(e) => handleTestCaseChange(index, e)}
            required
          />

          {form.testCases.length > 1 && (
            <button
              type="button"
              style={styles.removeBtn}
              onClick={() => removeTestCase(index)}
            >
              ❌ Remove
            </button>
          )}
        </div>
      ))}

      <button type="button" style={styles.addBtn} onClick={addTestCase}>
        ➕ Add Test Case
      </button>

      <button type="submit" style={styles.submitBtn}>
        ✅ Add Problem
      </button>
    </form>
  );
}

/* ================= STYLES ================= */

const styles = {
  form: {
    background: "#020617",
    padding: 20,
    borderRadius: 12,
    marginBottom: 20,
  },
  heading: {
    color: "#e5e7eb",
    marginBottom: 12,
  },
  input: {
    width: "100%",
    padding: 10,
